import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Matrix-vector multiplication: C (M,1) = A (M,K) * B (K,1)
// One thread block per output row. Threads stride over K with float4
// vectorized loads, accumulate a local partial dot product, then do a
// warp + shared-memory block reduction.
__global__ void matvec_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int K) {
    // Skinny GEMV (N == 1): tile the large M output dimension by processing
    // two rows per CTA while keeping the tiny N dimension inside the block.
    // This reuses each B fragment across two A rows and reduces launch tail.
    int row0 = blockIdx.x * 2;
    if (row0 >= M) return;
    int row1 = row0 + 1;
    bool has1 = row1 < M;
    const float* a0 = A + (long long)row0 * (long long)K;
    const float* a1 = has1 ? (A + (long long)row1 * (long long)K) : a0;
    int tid = threadIdx.x;
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    int K4 = K >> 2;  // number of float4 groups
    const float4* a04 = reinterpret_cast<const float4*>(a0);
    const float4* a14 = reinterpret_cast<const float4*>(a1);
    const float4* b4 = reinterpret_cast<const float4*>(B);
    for (int i = tid; i < K4; i += blockDim.x) {
        float4 bv = b4[i];
        float4 av0 = a04[i];
        sum0 += av0.x * bv.x + av0.y * bv.y + av0.z * bv.z + av0.w * bv.w;
        if (has1) {
            float4 av1 = a14[i];
            sum1 += av1.x * bv.x + av1.y * bv.y + av1.z * bv.z + av1.w * bv.w;
        }
    }
    // Handle any tail elements (K not divisible by 4)
    for (int i = (K4 << 2) + tid; i < K; i += blockDim.x) {
        float bv = B[i];
        sum0 += a0[i] * bv;
        if (has1) sum1 += a1[i] * bv;
    }
    // Warp-level reduction
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum0 += __shfl_down_sync(0xffffffffu, sum0, offset);
        sum1 += __shfl_down_sync(0xffffffffu, sum1, offset);
    }
    __shared__ float shared0[32];
    __shared__ float shared1[32];
    int lane = tid & 31;
    int wid  = tid >> 5;
    if (lane == 0) {
        shared0[wid] = sum0;
        shared1[wid] = has1 ? sum1 : 0.0f;
    }
    __syncthreads();
    int numWarps = (blockDim.x + 31) >> 5;
    if (wid == 0) {
        sum0 = (lane < numWarps) ? shared0[lane] : 0.0f;
        sum1 = (lane < numWarps) ? shared1[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum0 += __shfl_down_sync(0xffffffffu, sum0, offset);
            sum1 += __shfl_down_sync(0xffffffffu, sum1, offset);
        }
        if (lane == 0) {
            C[row0] = sum0;
            if (has1) C[row1] = sum1;
        }
    }
}
torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0) && B.size(1) == 1, "Shape mismatch");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    int M = A_c.size(0);
    int K = A_c.size(1);
    auto C = torch::empty({M, 1}, A_c.options());
    int threads = 256;
    int blocks = (M + 1) / 2;
    matvec_kernel<<<blocks, threads>>>(
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K);
    return C;
}
"""

cpp_src = "torch::Tensor matvec(torch::Tensor A, torch::Tensor B);"

matvec_module = load_inline(
    name="matvec_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["matvec"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matvec_module.matvec(A, B)

